      hu: ["3120 méteres magasságban fekszik", "900 méterrel a völgy felett található", "1692-ben alapították hivatalosan", "1998-ban súlyos tűzvész pusztított itt", "2005-re fejezték be a helyreállítást", "Guru Rinpoche 8. századi meditációs helye"],
      ro: ["Altitudine de 3.120 metri", "Situată la 900 de metri deasupra văii", "Fondată oficial în anul 1692", "Incendiu devastator în aprilie 1998", "Restaurare finalizată în 2005", "Cuprinde 4 temple principale"],
      en: ["Elevation of 3,120 meters", "Perched 900 meters above the valley", "Officially founded in 1692", "Devastating fire in April 1998", "Restoration completed in 2005", "Guru Rinpoches 8th-century meditation site"],
      es: ["Construido en 1692.", "Altitud: 3.120 metros sobre el nivel del mar.", "900 metros sobre el fondo del valle.", "Reconstrucción tras incendio: 1998-2005.", "4 templos principales.", "Visitantes anuales: más de 100.000."],
      pt: ["Construído em 1692.", "Altitude: 3.120 metros acima do nível do mar.", "900 metros acima do fundo do vale.", "Reconstrução após incêndio: 1998-2005.", "4 templos principais.", "Visitantes anuais: mais de 100.000."],
      fr: ["Construit en 1692.", "Altitude : 3 120 mètres d'altitude.", "900 mètres au-dessus de la vallée.", "Reconstruction après incendie : 1998-2005.", "4 temples principaux.", "Plus de 100 000 visiteurs par an."],
