      es: ["Fue fundado por Ngawang Namgyal.", "Alberga las cenizas de su padre.", "Se encuentra en una zona forestal tranquila."],
      pt: ["Foi fundado por Ngawang Namgyal.", "Abriga as cinzas do seu pai.", "Situa-se numa zona florestal tranquila."],
