      en: "A sacred site that is actually a gorge on the Tang Chhu river. Pema Lingpa is said to have discovered Guru Rinpoche's hidden treasures here.",
      es: "Un sitio sagrado que en realidad es un desfiladero en el río Tang Chhu. Aquí se dice que Pema Lingpa descubrió tesoros ocultos de Guru Rinpoche.",
      pt: "Um local sagrado que é, na verdade, um desfiladeiro no rio Tang Chhu. Diz-se que Pema Lingpa descobriu aqui tesouros escondidos de Guru Rinpoche.",
      fr: "Un site sacré qui est en réalité une gorge dans la rivière Tang Chhu. C'est ici que Pema Lingpa aurait découvert des trésors cachés de Guru Rinpoché.",
