      ro: ["Mănăstirea a fost înființată în anul 1613.", "Gyalse Pema Thinley este fondatorul acestui lăcaș sfânt.", "Este situată în valea glaciară Phobjikha din districtul Wangdue Phodrang.", "Găzduiește un festival anual dedicat macaralelor cu gât negru.", "Situl a fost restaurat complet pe parcursul a șase ani (2002-2008).", "Conține una dintre cele mai mari școli de studii budiste din țară."],
      en: ["The monastery was founded in 1613 by Gyalse Pema Thinley.", "It serves as the main seat of the Peling tradition in western Bhutan.", "The site is located in the Phobjikha Valley at an altitude of 2,900m.", "The valley is the winter habitat for endangered black-necked cranes.", "A major renovation of the monastery was completed in 2008.", "It features some of the finest examples of 17th-century woodcraft."],
