    description: {
      de: "Ein riesiger Klosterkomplex hoch über Thimphu, der durch eine steile Wanderung erreicht wird. Es war einst eines der reichsten Klöster des Landes.",
      hu: "Hatalmas kolostorkomplexum magasan Thimphu felett, amelyet meredek túrával lehet elérni. Egykor az ország egyik leggazdagabb kolostora volt.",
      ro: "Un complex monahal uriaș sus deasupra orașului Thimphu, la care se ajunge printr-o drumeție abruptă. A fost cândva una dintre cele mai bogate mănăstiri din țară.",
      en: "A massive monastery complex high above Thimphu, reached by a steep hike. It was once one of the wealthiest monasteries in the country.",
      es: "Un enorme complejo monástico en las alturas de Thimphu, al que se llega tras una empinada caminata. Antaño fue uno de los monasterios más ricos del país.",
      pt: "Um enorme complexo monástico bem acima de Thimphu, alcançado através de uma caminhada íngreme. Foi outrora um dos mosteiros mais ricos do país.",
      fr: "Un immense complexe monastique situé sur les hauteurs de Thimphu, accessible après une randonnée abrupte. C'était autrefois l'un des monastères les plus riches du pays.",
    },
