      de: ["Gegründet im 13. Jahrhundert.", "Umfasst zehn Tempel.", "Bietet Schutz für benachteiligte Mönche."],
      hu: ["A 13. században alapították.", "Tíz templomból áll.", "Hátrányos helyzetű szerzeteseknek nyújt menedéket."],
      ro: ["Fondată în secolul al XIII-lea.", "Cuprinde zece temple.", "Oferă adăpost călugărilor dezavantajați."],
      en: ["Founded in the 13th century.", "Comprises ten temples.", "Provides refuge for disadvantaged monks."],
      es: ["Fundado en el siglo XIII.", "Incluye diez templos.", "Ofrece refugio a monjes desfavorecidos."],
      pt: ["Fundado no século XIII.", "Inclui dez templos.", "Oferece proteção a monges carenciados."],
