      es: ["Fundación: Siglo XIII", "Número de monjes: aprox. 70", "Altitud: unos 3.000 m sobre el nivel del mar", "Fundador: Phajo Drugom Zhigpo", "Ruta desde Thimphu: aprox. 2 horas", "Afiliación: Escuela Drukpa Kagyü"],
      pt: ["Fundação: Século XIII", "Número de monges: cerca de 70", "Altitude: cerca de 3.000 m acima do nível do mar", "Fundador: Phajo Drugom Zhigpo", "Trilho de Thimphu: cerca de 2 horas", "Afiliação: Escola Drukpa Kagyü"],
